def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 2 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            min_r = min(y for y, x in comp)
            max_r = max(y for y, x in comp)
            min_c = min(x for y, x in comp)
            max_c = max(x for y, x in comp)
            shape = {(y - min_r, x - min_c) for y, x in comp}

            if max_r - min_r == 1 and max_c - min_c == 2:
                if shape == {(0, 1), (1, 0), (1, 1), (1, 2)}:
                    up += 1
                elif shape == {(0, 0), (0, 1), (0, 2), (1, 1)}:
                    down += 1

    out = [[0] * 6 for _ in range(3)]
    up_slots = [(0, 0), (2, 0), (0, 2), (2, 2)]
    down_slots = [(0, 3), (2, 3), (0, 5), (2, 5)]

    for r, c in up_slots[:min(up, 4)]:
        out[r][c] = 3
    for r, c in down_slots[:min(down, 4)]:
        out[r][c] = 1

    return out
